{
  "schemaVersion" : "2.2",
  "description" : "CloudOps Guardian governed process termination action",
  "parameters" : {
    "ProcessId" : {
      "type" : "String",
      "description" : "PID approved in the CloudOps Guardian remediation plan",
      "allowedPattern" : "^[1-9][0-9]*$"
    },
    "ExpectedProcessName" : {
      "type" : "String",
      "description" : "Process name observed during investigation and bound to the approved plan",
      "allowedPattern" : "^[A-Za-z0-9._+-]+$"
    }
  },
  "mainSteps" : [ {
    "action" : "aws:runShellScript",
    "name" : "terminateApprovedProcess",
    "inputs" : {
      "runCommand" : [ "PID=\"{{ ProcessId }}\"\nEXPECTED=\"{{ ExpectedProcessName }}\"\n\nCURRENT=$(ps -p \"$PID\" -o comm= | xargs)\n\nif [ -z \"$CURRENT\" ]; then\n  echo \"REFUSED: process no longer exists\"\n  exit 20\nfi\n\nif [ \"$CURRENT\" != \"$EXPECTED\" ]; then\n  echo \"REFUSED: process identity changed\"\n  exit 21\nfi\n\nkill \"$PID\"\n\necho \"Termination signal sent to validated process\"" ]
    }
  } ]
}
